#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> getNext(string p)
{
    int n = p.size();
    vector<int> ne(n, 0);
    for (int i = 1, j = 0; i < n; ++i)
    {
        while (j > 0 && p[i] != p[j]) j = ne[j - 1];
        if (p[i] == p[j]) j++;
        ne[i] = j;
    }
    return ne;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    string pat, txt;
    cin >> n >> pat >> m >> txt;
    vector<int> ne = getNext(pat);
    vector<int> ans;
    for (int i = 0, j = 0; i < m; ++i)
    {
        while (j > 0 && txt[i] != pat[j]) j = ne[j - 1];
        if (txt[i] == pat[j]) j++;
        if (j == n)
        {
            ans.push_back(i - n + 1);
            j = ne[j - 1];
        }
    }
    for (size_t i = 0; i < ans.size(); ++i)
    {
        if (i) cout << " ";
        cout << ans[i];
    }
    return 0;
}
